import * as fs from "node:fs";
import * as path from "node:path";
export default function (pi: any) {
  pi.registerTool({
    name: "fsx",
    label: "Fsx",
    description: "Harness helper: change the workspace outside the extension under test.",
    parameters: {
      type: "object",
      properties: {
        op: { type: "string" },
        path: { type: "string" },
        content: { type: "string" },
        target: { type: "string" },
        mtime: { type: "number" },
      },
      required: ["op", "path"],
    },
    async execute(_id: string, params: any, _signal: any, _update: any, ctx: any) {
      const p = path.resolve(ctx.cwd, params.path);
      if (params.op === "write") {
        fs.mkdirSync(path.dirname(p), { recursive: true });
        fs.writeFileSync(p, params.content ?? "");
      } else if (params.op === "unlink") {
        fs.unlinkSync(p);
      } else if (params.op === "utimes") {
        fs.utimesSync(p, params.mtime, params.mtime);
      } else if (params.op === "symlink") {
        fs.mkdirSync(path.dirname(p), { recursive: true });
        fs.symlinkSync(path.resolve(ctx.cwd, params.target), p, "dir");
      } else if (params.op === "find") {
        // every regular file named params.content under params.path, with its mtime
        const found: string[] = [];
        const walk = (dir: string) => {
          for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
            const full = path.join(dir, entry.name);
            if (entry.isDirectory()) walk(full);
            else if (entry.name === params.content) found.push(path.relative(p, full) + " " + fs.statSync(full).mtimeMs);
          }
        };
        walk(p);
        found.sort();
        return { content: [{ type: "text", text: found.join("\n") || "none" }], details: {} };
      } else if (params.op === "mkdir") {
        fs.mkdirSync(p, { recursive: true });
      } else {
        throw new Error("fsx: unknown op " + params.op);
      }
      return { content: [{ type: "text", text: "fsx " + params.op + " ok" }], details: {} };
    },
  });
}
